<script setup>
import { computed, ref, watch } from 'vue'
import { AlertTriangle, ArrowRight, Check, CheckCircle2, Clock3, FileText, Info, Search, ShieldCheck, X, XCircle } from 'lucide-vue-next'
import ModalShell from './ModalShell.vue'
import QuestionChart from './QuestionChart.vue'
import { friendlyDate, possibleDuplicates, previewText } from '../data/questionManagement.js'
const props = defineProps({ suggestions: { type: Array, required: true }, questions: { type: Array, required: true } })
const emit = defineEmits(['approve', 'reject', 'open-bank'])
const status = ref('pending'); const search = ref(''); const selectedId = ref(null)
const rejectModal = ref(false); const rejectionReason = ref(''); const notice = ref('')
const filtered = computed(() => [...props.suggestions].filter(item => item.status === status.value && (!search.value.trim() || `${item.question} ${item.topic} ${item.submittedBy}`.toLowerCase().includes(search.value.toLowerCase()))).sort((a,b)=>new Date(b.submittedAt)-new Date(a.submittedAt)))
watch(filtered, items => { if (!items.some(s => s.id === selectedId.value)) selectedId.value = items[0]?.id || null }, { immediate: true })
const selected = computed(() => props.suggestions.find(item => item.id === selectedId.value) || null)
const duplicates = computed(() => selected.value ? possibleDuplicates(selected.value.question, selected.value.task, props.questions) : [])
const exactDuplicate = computed(() => duplicates.value.some(q=>q.exact))
const needsVisual = computed(() => selected.value?.task === 1 && !selected.value?.visual && !selected.value?.visualNotes)
const pendingTotal = computed(() => props.suggestions.filter(s => s.status === 'pending').length)
function approve() { if (!selected.value || selected.value.status !== 'pending') return; if (exactDuplicate.value || needsVisual.value) { notice.value='Resolve the duplicate or missing visual requirement before approving.'; return }; emit('approve',selected.value.id); notice.value='Suggestion approved and added to the question bank as an unpublished draft.' }
function reject() { if (!selected.value || selected.value.status !== 'pending') return; emit('reject',{id:selected.value.id,reason:rejectionReason.value.trim()}); rejectModal.value=false; rejectionReason.value=''; notice.value='Suggestion rejected. The decision was saved in this demo.' }
</script>
<template>
  <section class="page-header"><div><p class="eyebrow">ADMIN / MODERATION</p><h1>Review Question Suggestions</h1><p class="page-subtitle">Review proposed questions before they enter the standardized question bank.</p></div><button class="btn btn-outline" @click="emit('open-bank')"><ArrowRight :size="16"/>Go to question bank</button></section>
  <div class="qm-page"><div v-if="notice" class="qm-inline-notice" role="status"><Info :size="17"/><span>{{notice}}</span><button @click="notice=''">Dismiss</button></div>
    <section class="qm-panel qm-review-header"><div class="qm-review-count"><span class="qm-review-icon"><ShieldCheck :size="20"/></span><div><strong>{{pendingTotal}} awaiting review</strong><p>Approving creates a draft, not a publicly assigned question.</p></div></div><div class="qm-tab-strip" role="group" aria-label="Suggestion status"><button v-for="s in [{id:'pending',label:'Pending'}, {id:'approved',label:'Approved'}, {id:'rejected',label:'Rejected'}]" :key="s.id" :class="{active:status===s.id}" @click="status=s.id">{{s.label}}</button></div></section>
    <div class="qm-review-grid"><section class="qm-panel qm-queue-panel"><label class="qm-search"><Search :size="17"/><input v-model="search" placeholder="Search suggestions…" aria-label="Search suggestions"/></label><div class="qm-queue-list"><button v-for="item in filtered" :key="item.id" class="qm-queue-entry" :class="{active:item.id===selectedId}" @click="selectedId=item.id"><span class="qm-queue-top"><span class="qm-task-pill">Task {{item.task}}</span><small>{{friendlyDate(item.submittedAt)}}</small></span><strong>{{previewText(item.question,135)}} <span v-if="item.isSample" class="qm-sample-inline">Sample</span></strong><span class="qm-queue-bottom">{{item.topic}} <span>·</span> {{item.submittedBy}}</span></button><div v-if="!filtered.length" class="qm-review-empty"><Clock3 :size="25"/><strong>No {{status}} suggestions</strong><p>Try a different filter or return when new suggestions arrive.</p></div></div></section>
    <section class="qm-panel qm-review-detail" v-if="selected"><div class="qm-panel-title"><div><h2>Review suggestion</h2><p>Submitted by {{selected.submittedBy}} · {{friendlyDate(selected.submittedAt)}}</p></div><span class="qm-status" :class="`qm-status-${selected.status}`">{{selected.status === 'pending'?'Pending Review':selected.status}}</span></div>
      <div class="qm-detail-info"><span><strong>Task type</strong> Task {{selected.task}}</span><span><strong>Topic</strong> {{selected.topic}}</span><span><strong>Source</strong> {{selected.source || 'Learner provided'}}</span></div>
      <div class="qm-detail-essay"><span>PROPOSED QUESTION</span><p>{{selected.question}}</p></div>
      <div v-if="selected.task===1" class="qm-review-visual"><strong>Task 1 visual</strong><div v-if="selected.visual" class="qm-review-img"><img v-if="selected.visual.startsWith('data:')" :src="selected.visual" alt="Proposed Task 1 visual"/><QuestionChart v-else :variant="selected.visual"/></div><p v-else class="qm-muted">No image attached. {{selected.visualNotes ? 'Visual requirements are described below.' : 'Visual requirements are missing.'}}</p><p v-if="selected.visualNotes" class="qm-visual-note">{{selected.visualNotes}}</p></div>
      <div class="qm-review-checks"><h3>Review checklist</h3><div><span :class="exactDuplicate?'qm-check-warning':'qm-check-ok'"><AlertTriangle v-if="exactDuplicate" :size="17"/><CheckCircle2 v-else :size="17"/></span><span>Duplicate check <small>{{exactDuplicate?'Identical bank question found':duplicates.length?'Possible match — review manually':'No close match detected by text heuristic'}}</small></span></div><div><span :class="needsVisual?'qm-check-warning':'qm-check-ok'"><AlertTriangle v-if="needsVisual" :size="17"/><CheckCircle2 v-else :size="17"/></span><span>Visual requirements <small>{{selected.task===2?'Not needed for Task 2':needsVisual?'Missing visual or visual description':'Visual or details provided'}}</small></span></div></div>
      <div v-if="duplicates.length" class="qm-duplicate"><AlertTriangle :size="18"/><div><strong>Potential duplicates</strong><ul><li v-for="q in duplicates" :key="q.id">{{previewText(q.question,145)}}</li></ul></div></div>
      <div v-if="selected.status==='pending'" class="qm-review-actions"><button class="btn btn-outline qm-reject-btn" @click="rejectionReason='';rejectModal=true"><XCircle :size="16"/>Reject suggestion</button><button class="btn btn-primary" :disabled="exactDuplicate || needsVisual" @click="approve"><Check :size="16"/>Approve to draft</button></div><div v-else class="qm-resolution"><CheckCircle2 v-if="selected.status==='approved'" :size="18"/><XCircle v-else :size="18"/><div><strong>{{selected.status==='approved'?'Approved':'Rejected'}}</strong><p>Reviewed by {{selected.reviewedBy || 'Demo Admin'}} on {{friendlyDate(selected.reviewedAt)}}<span v-if="selected.reason"> · {{selected.reason}}</span></p></div></div>
    </section><section v-else class="qm-panel qm-review-detail qm-review-empty"><FileText :size="30"/><strong>Nothing selected</strong><p>Select a suggestion from the list to inspect it.</p></section></div>
    <div class="qm-demo-note"><Info :size="16"/>Moderation is simulated in this browser. Server-side roles, approval transactions, and audit records must be implemented in ASP.NET.</div>
  </div>
  <ModalShell v-if="rejectModal" title="Reject suggested question?" @close="rejectModal=false"><p class="qm-dialog-copy">The suggestion will be marked Rejected and will not appear in the standardized question bank.</p><label class="qm-label" for="qm-reason">Reason for rejection (optional)</label><textarea id="qm-reason" v-model="rejectionReason" rows="4" maxlength="500" class="qm-control qm-textarea" placeholder="Explain what the learner could improve…"/><template #footer><button class="btn btn-outline" @click="rejectModal=false">Cancel</button><button class="btn btn-primary" @click="reject"><X :size="16"/>Confirm rejection</button></template></ModalShell>
</template>
